+        return value;
+    }
+
+    default void writeIfNotNull(ByteBuf out, String key, Object value) {
+        if (value != null) {
+            RocketMQSerializable.writeStr(out, true, key);
+            RocketMQSerializable.writeStr(out, false, value.toString());
+        }
+    }
