+        ymlMap.put(AclConstants.CONFIG_ACCOUNTS, plainAccessConfigList);
+
+        // write prepared PlainAccessConfigs to file
+        final String aclConfigFile = System.getProperty("rocketmq.home.dir") + File.separator + "conf/plain_acl.yml";
